from pathlib import Path
root=Path("build-src/MediAgenda_Android_v1")
src=root/"app/src/main/java/com/mediagenda/app"
file=src/"MainActivity.kt"
s=file.read_text(encoding="utf-8")
def insert_once(before,after,extra,label):
    global s
    anchor=before+after
    if s.count(anchor)!=1: raise RuntimeError(f"v1.9.42 {label}: {s.count(anchor)} anchors")
    s=s.replace(anchor,before+extra+after,1)
insert_once('import com.google.mlkit.vision.text.latin.TextRecognizerOptions\nimport com.mediagenda.app.data.DataRepository\nimport com.mediagenda.app.data.ProfileStore\n','import com.mediagenda.app.data.AppPinStore\nimport com.mediagenda.app.i18n.AppLanguage\nimport com.mediagenda.app.data.FamilyBackupStore\n','import com.mediagenda.app.data.ProfileDeletionStore\n',"section_0")
insert_once('\n    override fun onResume() {\n        super.onResume()\n','        // Fallback for camera apps that do not deliver a reliable ActivityResult.\n        // If image bytes are really present, the same private capture is shown.\n        window.decorView.postDelayed({\n','        val syncState=getSharedPreferences("saudepratica_nearby_sync_ui_v2",MODE_PRIVATE)\n        val latest=syncState.getLong("last_import_complete",0L)\n        val shown=syncState.getLong("main_last_shown",0L)\n        if(latest>0 && latest>shown && ::content.isInitialized && ::repo.isInitialized){\n            syncState.edit().putLong("main_last_shown",latest).apply()\n            window.decorView.post{\n                if(!isFinishing && !isDestroyed){\n                    if(profiles.all().none{it.id==activeProfileId}){\n                        showProfileSelection()\n                    }else{\n                        // Existing views contain old data; rebuild from disk.\n                        showHome()\n                    }\n                    Toast.makeText(this,\n                        "Sincronização recebida. Os dados apresentados foram atualizados.",\n                        Toast.LENGTH_LONG).show()\n                }\n            }\n        }\n',"section_1")
insert_once('        }\n    }\n\n','    private fun showNotificationsMenu(){\n        content.removeAllViews()\n        screenHeader("🔔","Notificações","Testes e permissões por tipo de aviso")\n','    private fun showDeleteProfilePicker() {\n        val existing=profiles.all()\n        if(existing.isEmpty()) {\n            showError("Não existem utilizadores para eliminar.")\n            return\n        }\n        MaterialAlertDialogBuilder(this)\n            .setTitle("🗑 Eliminar utilizador")\n            .setMessage("Escolhe APENAS o perfil a eliminar. Os dados dos outros " +\n                "utilizadores não serão apagados.")\n            .setItems(existing.map{it.name}.toTypedArray()){_,index ->\n                confirmDeleteSelectedProfile(existing[index])\n            }\n            .setNegativeButton("Cancelar",null)\n            .show()\n    }\n\n    private fun confirmDeleteSelectedProfile(profile:HealthProfile) {\n        val form=formBox()\n        form.addView(noteBox("Ação irreversível — " + profile.name,\n            "Serão apagados DESTE telemóvel os dados de identificação, " +\n            "medicação, tomas, consultas, documentos, exames, despesas, " +\n            "fotografias exclusivas e definições deste utilizador. " +\n            "Os outros perfis serão preservados. " +\n            "Faz primeiro um backup em Mais → Backup completo da família. " +\n            "ATENÇÃO: a sincronização não propaga eliminações; o perfil " +\n            "pode regressar se existir no outro telemóvel."))\n        val phrase=input("Para confirmar, escreve: " + profile.name, "")\n        form.addView(phrase.container)\n        val pinStore=AppPinStore(this)\n        val pin=if(pinStore.enabled())input("PIN da SaúdePrática (4 dígitos)", "") else null\n        pin?.let{\n            it.edit.inputType=InputType.TYPE_CLASS_NUMBER or\n                InputType.TYPE_NUMBER_VARIATION_PASSWORD\n            form.addView(it.container)\n        }\n        val dialog=MaterialAlertDialogBuilder(this)\n            .setTitle("Eliminar definitivamente " + profile.name + "?")\n            .setView(scroll(form))\n            .setNegativeButton("Cancelar",null)\n            .setPositiveButton("Eliminar perfil e dados",null)\n            .show()\n        dialog.getButton(androidx.appcompat.app.AlertDialog.BUTTON_POSITIVE)\n            .setTextColor(Color.parseColor("#B42318"))\n        dialog.getButton(androidx.appcompat.app.AlertDialog.BUTTON_POSITIVE).setOnClickListener{\n            if(phrase.edit.text.toString().trim()!=profile.name){\n                phrase.edit.error="Escreve exatamente o nome do utilizador."\n                return@setOnClickListener\n            }\n            if(pin!=null&&!pinStore.verify(pin.edit.text.toString())){\n                pin.edit.error="PIN incorreto ou temporariamente bloqueado."\n                return@setOnClickListener\n            }\n            try{\n                val removed=ProfileDeletionStore(this).delete(profile.id)\n                val currentRemoved=activeProfileId==profile.id\n                dialog.dismiss()\n                reschedule()\n                if(currentRemoved){\n                    val remaining=profiles.all()\n                    if(remaining.isNotEmpty())activateProfile(remaining.first())\n                    else{\n                        activeProfileId="legacy"\n                        repo=DataRepository(this,"legacy")\n                        showProfileSelection()\n                        showCreateProfileDialog()\n                    }\n                } else showDataTools()\n                Toast.makeText(this,"Utilizador $removed eliminado deste telemóvel.",\n                    Toast.LENGTH_LONG).show()\n            }catch(error:Exception){\n                showError("Não foi possível concluir a eliminação: " +\n                    (error.localizedMessage?:"erro desconhecido"))\n            }\n        }\n    }\n\n',"section_2")
insert_once('        })\n        box.addView(infoCard("➕", "Adicionar utilizador", "Criar um perfil com medicação e agenda próprias, sem palavra-passe") {\n            showCreateProfileDialog()\n','        })\n        box.addView(infoCard("☑", "Escolher módulos do Início",\n            "Selecionar com checklist o que aparece no menu principal") {\n','        })\n        box.addView(infoCard("🗑", "Eliminar utilizador e respetivos dados",\n            "Apagar um perfil selecionado, com confirmação reforçada") {\n            showDeleteProfilePicker()\n',"section_3")
