for rel in ("data/ProfileStore.kt","data/ProfileDeletionStore.kt","sync/NearbySyncActivity.kt"):
    target=src/rel
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(Path("MediAgenda/v61_overrides",rel).read_text(encoding="utf-8"),encoding="utf-8")
gradle=root/"app/build.gradle.kts"
